//! The old versions of some functions that glibc 2.43 still exports under their first symbol version (`regexec@GLIBC_2.2.5`,
//! `sched_getaffinity@GLIBC_2.3.3`, `pthread_cond_wait@GLIBC_2.2.5`, ...), for programs built long ago, and for static
//! programs that name an old version with `.symver`. glibc keeps them as `compat_symbol`s whose function differs from
//! the current one in a detail; the versions whose function is the same are plain aliases (compat_symver.rs, generated by
//! hdrgen compat-symver). Each function here is exported under a private name and given its old version name by
//! compat_symver.rs. The behaviour follows glibc 2.43's compat code (posix/regexec.c, stdlib/canonicalize.c, io/ftw.c,
//! nptl/old_pthread_cond_*.c, sysdeps/unix/sysv/linux/{sched_*affinity,speed,timer_*}.c, stdlib/quick_exit.c), read as
//! reference; the code is Rust.
use core::ffi::{c_char, c_int, c_void};
use core::sync::atomic::{AtomicPtr, Ordering};
use rusty_libc_core::errno;

const EINVAL: i32 = 22;
const ENOMEM: i32 = 12;

/// `regexec@GLIBC_2.2.5`: the old function knew only REG_NOTBOL and REG_NOTEOL (REG_STARTEND came with the 2.3.4
/// version); every other flag is dropped (glibc posix/regexec.c `__compat_regexec`).
///
/// # Safety
/// As `regexec`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __rl_compat_regexec(preg: *const rusty_libc_regex::cabi::RegexT, string: *const c_char, nmatch: usize, pmatch: *mut rusty_libc_regex::cabi::RegMatch, eflags: c_int) -> c_int {
    // SAFETY: the contract is the function's (see `# Safety`).
    unsafe { rusty_libc_regex::cabi::regexec(preg, string, nmatch, pmatch, eflags & 3 /* REG_NOTBOL | REG_NOTEOL */) }
}

/// `realpath@GLIBC_2.2.5`: a NULL `resolved` is EINVAL (the old interface had no allocating form).
///
/// # Safety
/// As `realpath`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __rl_compat_realpath(path: *const c_char, resolved: *mut c_char) -> *mut c_char {
    if resolved.is_null() {
        errno::set(EINVAL);
        return core::ptr::null_mut();
    }
    // SAFETY: the contract is `realpath`'s, with a non-NULL `resolved`.
    unsafe { rusty_libc_stdlib::misc::realpath(path, resolved) }
}

const FTW_OLD_FLAGS: c_int = 1 /* FTW_PHYS */ | 2 /* FTW_MOUNT */ | 4 /* FTW_CHDIR */ | 8 /* FTW_DEPTH */;

/// `nftw@GLIBC_2.2.5`: the old function ignored every flag it did not know (FTW_ACTIONRETVAL).
///
/// # Safety
/// As `nftw`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __rl_compat_nftw(path: *const c_char, func: rusty_libc_extra::ftw::NftwFunc, descriptors: c_int, flags: c_int) -> c_int {
    // SAFETY: the contract is the function's (see `# Safety`).
    unsafe { rusty_libc_extra::ftw::nftw(path, func, descriptors, flags & FTW_OLD_FLAGS) }
}

/// `nftw64@GLIBC_2.2.5`.
///
/// # Safety
/// As `nftw64`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __rl_compat_nftw64(path: *const c_char, func: rusty_libc_extra::ftw::NftwFunc, descriptors: c_int, flags: c_int) -> c_int {
    // SAFETY: the contract is the function's (see `# Safety`).
    unsafe { rusty_libc_extra::ftw::nftw64(path, func, descriptors, flags & FTW_OLD_FLAGS) }
}

