/// `stime`: compat_symver.rs jumps to this name for `stime@GLIBC_2.2.5`; glibc has no default version of it, so only the shared
/// build (where every member of the archive is linked) defines it, and the version script keeps it local.
///
/// # Safety
/// `when` points at a readable `time_t`.
#[cfg(feature = "shared")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn stime(when: *const i64) -> c_int {
    // SAFETY: the contract is the function's (see `# Safety`).
    unsafe { rusty_libc_time::clock::stime(when) }
}
